// The sub-block of parent named word, or null when parent has no such sub-block.
inline const Pov4BlockSchema* FindPov4NestedSchema(const std::string& parent, const std::string& word)
{
    for (const Pov4NestedSchema& s : kPov4NestedSchemas)
        if ((parent == s.parent) && (word == s.block.word)) return &s.block;
    return nullptr;
}

// The sub-blocks of parent that take item, joined by " or ", or empty when none does.
inline std::string Pov4NestedOwners(const std::string& parent, const std::string& item)
{
    std::string owners;
    for (const Pov4NestedSchema& s : kPov4NestedSchemas)
        if (parent == s.parent)
            for (size_t i = 0; i < s.block.count; ++i)
                if (item == s.block.items[i])
                {
                    owners += (owners.empty() ? "" : " or ") + std::string(s.block.word);
                    break;
                }
    return owners;
}

